// app/api/woocommerce/abandoned-cart/route.ts
//
// Ingestion endpoint for the "CartRenew for WooCommerce" WordPress plugin.
// The plugin POSTs here (see includes/class-cr-api.php) whenever its WP-Cron
// sweep finds a cart that's been inactive past the configured wait time,
// with a phone number and consent on file.
//
// Auth: Authorization: Bearer <api_key>  — the api_key must match the
// `stores.api_key` column for the given `store_id`. store_id itself is the
// existing CartRenew store UUID (shown in the merchant dashboard) — it is
// NOT generated by this endpoint, only verified.

import { NextRequest, NextResponse } from 'next/server'
import { brand } from '@/lib/brand'
import { legacyCommerceRouteEnabled } from '@/lib/privacy/legacy-commerce'
import { supabaseAdmin } from '@/lib/supabase'
import { maskPhone, toE164 } from '@/lib/phone'
import { triggerWhatsAppRecoveryForCart } from '@/lib/services/messaging'
import { evaluateTrialCap, resolveFreeMessageLimit } from '@/lib/woocommerce/trial-cap'

export const dynamic = 'force-dynamic'
export const runtime = 'nodejs'

const UPGRADE_URL = 'https://www.cartrenew.com/en#pricing'

/**
 * Counts messages WhatsApp already accepted for this store and applies the
 * free-message cap. Fails OPEN on lookup errors: a database hiccup must not
 * silently stop paying merchants from recovering carts.
 */
async function checkTrialCap(storeId: string, billingStatus: string | null) {
  const defaultLimit = resolveFreeMessageLimit(process.env.WOOCOMMERCE_FREE_MESSAGE_LIMIT)

  // Fast path: paid stores never need the count.
  if ((billingStatus ?? '').toLowerCase() === 'active') {
    return evaluateTrialCap({ billingStatus, messageCapOverride: null, used: 0, defaultLimit })
  }

  // Optional per-store override. Separate query so the route keeps working
  // before the message_cap_override migration has been applied.
  let messageCapOverride: number | null = null
  const { data: overrideRow, error: overrideError } = await supabaseAdmin
    .from('stores')
    .select('message_cap_override')
    .eq('id', storeId)
    .maybeSingle()
  if (!overrideError && overrideRow && typeof overrideRow.message_cap_override === 'number') {
    messageCapOverride = overrideRow.message_cap_override
  }

  const { count, error: countError } = await supabaseAdmin
    .from('messages')
    .select('id', { count: 'exact', head: true })
    .eq('store_id', storeId)
    .in('status', ['sent', 'delivered', 'read'])

  if (countError) {
    console.error('CartRenew WooCommerce: trial cap count failed, allowing send', countError)
    return evaluateTrialCap({ billingStatus, messageCapOverride, used: 0, defaultLimit })
  }

  return evaluateTrialCap({ billingStatus, messageCapOverride, used: count ?? 0, defaultLimit })
}

interface WooCommerceCartItem {
  name: string
  quantity: number
  price: number | string
}

interface WooCommerceAbandonedCartPayload {
  store_id: string
  cart_key: string
  customer_name?: string | null
  phone_number: string
  cart_total: number | string
  checkout_url: string
  cart_contents: WooCommerceCartItem[]
  site_url?: string
}

export async function POST(req: NextRequest) {
  if (!legacyCommerceRouteEnabled(brand.isDefault)) {
    return NextResponse.json({ error: 'Not found' }, { status: 404 })
  }

  // --- 1. Auth ---------------------------------------------------------
  const authHeader = req.headers.get('authorization') || ''
  const apiKey = authHeader.startsWith('Bearer ')
    ? authHeader.slice('Bearer '.length).trim()
    : null

  if (!apiKey) {
    return NextResponse.json(
      { error: 'Missing Authorization: Bearer <api_key> header.' },
      { status: 401 }
    )
  }

  let payload: WooCommerceAbandonedCartPayload
  try {
    payload = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body.' }, { status: 400 })
  }

  const { store_id, cart_key, phone_number, checkout_url, cart_contents } = payload

  if (!store_id || !cart_key || !phone_number || !checkout_url) {
    return NextResponse.json(
      { error: 'store_id, cart_key, phone_number and checkout_url are required.' },
      { status: 400 }
    )
  }

  // stores has no `name` column — only select fields that exist.
  const { data: store, error: storeError } = await supabaseAdmin
    .from('stores')
    .select('id, api_key, billing_status')
    .eq('id', store_id)
    .maybeSingle()

  if (storeError || !store) {
    return NextResponse.json({ error: 'Unknown store_id.' }, { status: 404 })
  }

  if (!store.api_key || store.api_key !== apiKey) {
    return NextResponse.json({ error: 'Invalid API key for this store.' }, { status: 401 })
  }

  // --- 2. Idempotency: don't double-send for the same cart -------------
  // external_cart_key is a generic column (platform + cart_key combined)
  // so WooCommerce, Shopify, and future platforms share abandoned_carts.
  const externalCartKey = `woocommerce:${store_id}:${cart_key}`

  const { data: existing } = await supabaseAdmin
    .from('abandoned_carts')
    .select('id, status')
    .eq('external_cart_key', externalCartKey)
    .maybeSingle()

  // Schema check: status ∈ pending | messaged | recovered | lost | opted_out
  // (not "sent" — that was a mismatch with the live CHECK constraint)
  if (existing && existing.status === 'messaged') {
    return NextResponse.json({ status: 'already_sent' }, { status: 200 })
  }
  // recovered / lost / opted_out carts must never get another reminder.
  if (existing && existing.status !== 'pending') {
    return NextResponse.json({ status: existing.status }, { status: 200 })
  }

  if (existing) {
    const { data: priorMessages } = await supabaseAdmin
      .from('messages')
      .select('id')
      .eq('cart_id', existing.id)
      .limit(1)
    // A send was already attempted; the retry worker owns this cart now.
    if (priorMessages?.length) {
      return NextResponse.json({ status: 'retry_scheduled' }, { status: 202 })
    }
  }

  // --- 2b. Free-message cap ----------------------------------------------
  // Every WhatsApp template costs money and stores registered through
  // register-store start unpaid, so cap the free messages per store. Paid
  // (billing_status "active") and overridden stores are exempt.
  const capDecision = await checkTrialCap(store_id, store.billing_status)
  if (!capDecision.allowed) {
    return NextResponse.json(
      {
        status: 'trial_limit_reached',
        error: 'Free message limit reached. Upgrade your CartRenew plan to keep sending recovery messages.',
        limit: capDecision.limit,
        used: capDecision.used,
        upgrade_url: UPGRADE_URL,
      },
      { status: 402 }
    )
  }

  // The plugin sends E.164 built from the billing country; older plugin
  // versions send what the shopper typed, and bare national numbers are refused.
  const normalizedPhone = toE164(phone_number)
  const customerPhone = normalizedPhone.ok ? normalizedPhone.e164 : phone_number

  const cartValue = Number(payload.cart_total) || 0
  const items = (cart_contents || []).map((item) => ({
    name: item.name,
    title: item.name,
    quantity: Number(item.quantity) || 1,
    price: Number(item.price) || 0,
  }))

  let cartId = existing?.id

  if (!cartId) {
    // shopify_cart_token is NOT NULL on legacy schema — fill with the Woo
    // external key so the (store_id, shopify_cart_token) unique index stays valid.
    const { data: inserted, error: insertError } = await supabaseAdmin
      .from('abandoned_carts')
      .insert({
        store_id,
        platform: 'woocommerce',
        external_cart_key: externalCartKey,
        shopify_cart_token: externalCartKey,
        customer_name: payload.customer_name || null,
        customer_phone: customerPhone,
        checkout_url,
        cart_value: cartValue,
        items,
        status: 'pending',
      })
      .select('id')
      .single()

    if (insertError || !inserted) {
      console.error('CartRenew WooCommerce: failed to insert abandoned cart', insertError)
      return NextResponse.json({ error: 'Failed to record cart.' }, { status: 500 })
    }
    cartId = inserted.id
  } else {
    await supabaseAdmin
      .from('abandoned_carts')
      .update({ customer_phone: customerPhone })
      .eq('id', cartId)
  }

  if (!normalizedPhone.ok) {
    console.warn('CartRenew WooCommerce: phone not sendable, no WhatsApp sent', {
      cartId,
      reason: normalizedPhone.reason,
      phone: maskPhone(phone_number),
    })
  }

  // --- 3. Send the WhatsApp recovery message ----------------------------
  // triggerWhatsAppRecoveryForCart returns { sent, error } — it does not throw
  // on soft send failures, so check result.sent explicitly.
  try {
    const result = await triggerWhatsAppRecoveryForCart({
      storeId: store_id,
      cartId,
      customerPhone,
      customerName: payload.customer_name || null,
      checkoutUrl: checkout_url,
      cartValue,
      items,
      customerEmail: null,
      cartToken: cart_key,
    })

    // Cart status/failure bookkeeping happens in triggerWhatsAppRecoveryForCart:
    // 'messaged' only after Graph accepts, failures recorded on the cart.
    if (result.sent) {
      return NextResponse.json({ status: 'sent', result }, { status: 200 })
    }

    if (result.retryScheduled) {
      return NextResponse.json(
        { status: 'retry_scheduled', error: result.error || 'WhatsApp send failed.' },
        { status: 202 }
      )
    }

    if (result.error?.startsWith('phone_')) {
      return NextResponse.json({ status: 'not_sent', error: result.error }, { status: 422 })
    }

    return NextResponse.json(
      { status: 'failed', error: result.error || 'WhatsApp send failed.' },
      { status: 502 }
    )
  } catch (err) {
    console.error('CartRenew WooCommerce: WhatsApp send failed', err)
    return NextResponse.json({ error: 'WhatsApp send failed.' }, { status: 502 })
  }
}
